use crate::details::{
    driver_details, format_details, format_tag_details, FormatDetails, FormatTagDetails,
    FORMATTAG_FORMATTAG, FORMATTAG_INDEX, FORMATTAG_LARGESTSIZE, FORMAT_FORMAT, FORMAT_INDEX,
};
use crate::format::{format_index, init_adpcm, samples_per_block, Coef, WaveFormat};
use crate::size::{stream_size, StreamSize, SIZE_DESTINATION, SIZE_SOURCE};
use crate::suggest::{
    format_suggest, Suggest, SUGGEST_NCHANNELS, SUGGEST_NSAMPLESPERSEC, SUGGEST_WBITSPERSAMPLE,
    SUGGEST_WFORMATTAG,
};
use crate::{Error, WAVE_FORMAT_ADPCM, WAVE_FORMAT_PCM};

