struct Args<'a> {
    words: std::str::SplitWhitespace<'a>,
}

impl<'a> Args<'a> {
    fn word(&mut self) -> &'a str {
        self.words.next().expect("missing argument")
    }

    fn number(&mut self) -> u64 {
        self.word().parse().expect("numeric argument")
    }

    fn format(&mut self) -> WaveFormat {
        WaveFormat {
            format_tag: self.number() as u16,
            channels: self.number() as u16,
            samples_per_sec: self.number() as u32,
            avg_bytes_per_sec: self.number() as u32,
            block_align: self.number() as u16,
            bits_per_sample: self.number() as u16,
            cb_size: self.number() as u16,
            samples_per_block: self.number() as u16,
            ..Default::default()
        }
    }
}

fn code(result: Result<(), Error>) -> u32 {
    match result {
        Ok(()) => 0,
        Err(e) => e.code(),
    }
}

fn format_text(f: &WaveFormat) -> String {
    let mut text = format!(
        "{} {} {} {} {} {} {} {} {}",
        f.format_tag,
        f.channels,
        f.samples_per_sec,
        f.avg_bytes_per_sec,
        f.block_align,
        f.bits_per_sample,
        f.cb_size,
        f.samples_per_block,
        f.num_coef
    );
    for c in f.coef {
        text.push_str(&format!(" {} {}", c.i_coef1, c.i_coef2));
    }
    text
}

fn hex_text(bytes: &[u8]) -> String {
    if bytes.is_empty() {
        return "-".to_string();
    }
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn parse_hex(text: &str) -> Vec<u8> {
    (0..text.len() / 2)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).expect("hex byte"))
        .collect()
}

/// Runs one harness command line and returns the harness output line.
fn replay(command: &str) -> String {
    let mut args = Args {
        words: command.split_whitespace(),
    };
    match args.word() {
        "index" => {
            let fmt = args.format();
            format_index(&fmt).unwrap_or(u32::MAX).to_string()
        }
        "tagdetails" => {
            let query = args.number() as u32;
            let mut d = FormatTagDetails {
                index: args.number() as u32,
                format_tag: args.number() as u32,
                ..Default::default()
            };
            let rc = code(format_tag_details(query, &mut d));
            format!(
                "{rc} {} {} {} {} {} {}",
                d.index, d.format_tag, d.support, d.format_size, d.standard_formats, d.name
            )
        }
        "details" => {
            let query = args.number() as u32;
            let mut d = FormatDetails {
                format_tag: args.number() as u32,
                format_index: args.number() as u32,
                cb_wfx: args.number() as u32,
                support: 0,
            };
            let mut fmt = args.format();
            let rc = code(format_details(query, &mut d, &mut fmt));
            format!("{rc} {} {}", d.support, format_text(&fmt))
        }
        "suggest" => {
            let s = Suggest {
                fdw_suggest: args.number() as u32,
                cb_src: args.number() as u32,
                cb_dst: args.number() as u32,
            };
            let src = args.format();
            let mut dst = args.format();
            let rc = code(format_suggest(&s, &src, &mut dst));
            format!("{rc} {}", format_text(&dst))
        }
        "size" => {
            let mut s = StreamSize {
                fdw_size: args.number() as u32,
                src_length: args.number() as u32,
                dst_length: args.number() as u32,
            };
            let src = args.format();
            let dst = args.format();
            let rc = code(stream_size(&src, &dst, &mut s));
            format!("{rc} {} {}", s.src_length, s.dst_length)
        }
        "open" => {
            let fdw_open = args.number() as u32;
            let src = args.format();
            let dst = args.format();
            match stream_open(fdw_open, &src, &dst) {
                Ok(decoder) => match decoder.kind() {
                    Kind::Mono => "0 mono".to_string(),
                    Kind::Stereo => "0 stereo".to_string(),
                },
                Err(e) => format!("{} -", e.code()),
            }
        }
        "convert" => {
            let hex = args.word();
            let dst_len = args.number() as usize;
            let src_fmt = args.format();
            let dst_fmt = args.format();
            let input = if hex == "-" {
                Vec::new()
            } else {
                parse_hex(hex)
            };
            match stream_open(0, &src_fmt, &dst_fmt) {
                Err(e) => format!("{} 0 0 -", e.code()),
                Ok(decoder) => {
                    let mut out = vec![0u8; dst_len];
                    let usage = decoder.convert(&input, &mut out);
                    format!(
                        "0 {} {} {}",
                        usage.src_used,
                        usage.dst_used,
                        hex_text(&out[..usage.dst_used])
                    )
                }
            }
        }
        "driver" => {
            let d = driver_details();
            format!(
                "0 {} {} {} {} {} {} {} {} {} {}|{}|{}|{}|{}",
                d.fcc_type,
                d.fcc_comp,
                d.manufacturer_id,
                d.product_id,
                d.acm_version,
                d.driver_version,
                d.support,
                d.format_tags,
                d.filter_tags,
                d.short_name,
                d.long_name,
                d.copyright,
                d.licensing,
                d.features
            )
        }
        other => panic!("unknown harness command {other}"),
    }
}

#[test]
fn oracle_vectors_match_wine() {
    for &(command, expected) in VECTORS {
        assert_eq!(replay(command), expected, "{command}");
    }
}

#[test]
#[should_panic(expected = "unknown harness command bogus")]
fn unknown_command_panics() {
    replay("bogus");
}

fn pcm(channels: u16, rate: u32, bits: u16) -> WaveFormat {
    let block_align = channels * bits / 8;
    WaveFormat {
        format_tag: WAVE_FORMAT_PCM,
        channels,
        samples_per_sec: rate,
        avg_bytes_per_sec: rate * u32::from(block_align),
        block_align,
        bits_per_sample: bits,
        ..Default::default()
    }
}

fn adpcm(channels: u16, rate: u32, block_align: u16) -> WaveFormat {
    let mut f = WaveFormat {
        format_tag: WAVE_FORMAT_ADPCM,
        channels,
        samples_per_sec: rate,
        block_align,
        bits_per_sample: 4,
        cb_size: 32,
        ..Default::default()
    };
    f.samples_per_block = samples_per_block(block_align, channels).expect("channels");
    f
}

#[test]
fn format_index_accepts_unlisted_layouts() {
    assert_eq!(format_index(&pcm(1, 48000, 16)), Some(16));
    assert_eq!(format_index(&pcm(2, 48000, 16)), Some(16));
    let mut f = pcm(1, 48000, 16);
    f.avg_bytes_per_sec = 1;
    assert_eq!(format_index(&f), None);
    let mut f = pcm(1, 48000, 16);
    f.block_align = 4;
    assert_eq!(format_index(&f), None);
    let mut f = pcm(1, 48000, 16);
    f.bits_per_sample = 8;
    assert_eq!(format_index(&f), None);
    let mut f = pcm(1, 48000, 16);
    f.channels = 3;
    assert_eq!(format_index(&f), None);
    let mut f = pcm(1, 48000, 16);
    f.channels = 0;
    assert_eq!(format_index(&f), None);
    let mut f = adpcm(2, 16000, 64);
    assert_eq!(format_index(&f), Some(8));
    f.cb_size = 31;
    assert_eq!(format_index(&f), None);
    let mut f = adpcm(2, 16000, 64);
    f.bits_per_sample = 8;
    assert_eq!(format_index(&f), None);
    let mut f = adpcm(2, 16000, 64);
    f.channels = 0;
    assert_eq!(format_index(&f), None);
    let mut f = adpcm(2, 16000, 64);
    f.format_tag = 3;
    assert_eq!(format_index(&f), None);
}

#[test]
fn init_adpcm_covers_each_rate_class() {
    let mut f = WaveFormat {
        format_tag: WAVE_FORMAT_ADPCM,
        channels: 1,
        samples_per_sec: 48000,
        block_align: 6,
        bits_per_sample: 4,
        avg_bytes_per_sec: 1234,
        ..Default::default()
    };
    init_adpcm(&mut f);
    assert_eq!((f.cb_size, f.block_align), (0, 6));

    f.cb_size = 32;
    init_adpcm(&mut f);
    assert_eq!(f.block_align, 6);
    assert_eq!(f.samples_per_block, 0);
    assert_eq!(f.avg_bytes_per_sec, 1234);
    assert_eq!(f.num_coef, 7);

    let mut f = adpcm(1, 11025, 256);
    f.block_align = 0;
    init_adpcm(&mut f);
    assert_eq!(f.block_align, 256);
    assert_eq!(f.samples_per_block, 500);
    assert_eq!(f.avg_bytes_per_sec, 5644);

    let mut f = adpcm(2, 44100, 0);
    init_adpcm(&mut f);
    assert_eq!(f.block_align, 2048);
    assert_eq!(f.samples_per_block, 2036);

    assert_eq!(samples_per_block(32, 0), None);
    assert_eq!(samples_per_block(6, 1), Some(0));
}

#[test]
fn format_tag_details_covers_each_query() {
    let mut d = FormatTagDetails {
        index: 1,
        ..Default::default()
    };
    assert_eq!(format_tag_details(FORMATTAG_INDEX, &mut d), Ok(()));
    assert_eq!((d.format_tag, d.name), (2, "Microsoft ADPCM"));

    let mut d = FormatTagDetails {
        format_tag: 1,
        ..Default::default()
    };
    assert_eq!(format_tag_details(FORMATTAG_FORMATTAG, &mut d), Ok(()));
    assert_eq!((d.index, d.name), (0, "PCM"));

    let mut d = FormatTagDetails {
        format_tag: 2,
        ..Default::default()
    };
    assert_eq!(format_tag_details(FORMATTAG_LARGESTSIZE, &mut d), Ok(()));
    assert_eq!(d.index, 1);

    let mut d = FormatTagDetails {
        format_tag: 1,
        ..Default::default()
    };
    assert_eq!(format_tag_details(FORMATTAG_LARGESTSIZE, &mut d), Ok(()));
    assert_eq!(d.index, 0);

    let mut d = FormatTagDetails {
        format_tag: 3,
        ..Default::default()
    };
    assert_eq!(
        format_tag_details(FORMATTAG_FORMATTAG, &mut d),
        Err(Error::NotPossible)
    );
    assert_eq!(
        format_tag_details(FORMATTAG_LARGESTSIZE, &mut d),
        Err(Error::NotPossible)
    );
}

#[test]
fn format_details_covers_each_query() {
    let mut d = FormatDetails {
        format_tag: 1,
        format_index: 16,
        cb_wfx: 16,
        support: 0,
    };
    let mut fmt = WaveFormat::default();
    assert_eq!(
        format_details(FORMAT_INDEX, &mut d, &mut fmt),
        Err(Error::NotPossible)
    );
    assert_eq!(fmt.format_tag, 1);

    let mut d = FormatDetails {
        format_tag: 2,
        format_index: 8,
        cb_wfx: 50,
        support: 0,
    };
    let mut fmt = WaveFormat::default();
    assert_eq!(
        format_details(FORMAT_INDEX, &mut d, &mut fmt),
        Err(Error::NotPossible)
    );

    let mut d = FormatDetails {
        format_tag: 1,
        format_index: 16,
        cb_wfx: 16,
        support: 0,
    };
    let mut fmt = pcm(1, 8000, 8);
    assert_eq!(format_details(FORMAT_FORMAT, &mut d, &mut fmt), Ok(()));
    assert_eq!(d.support, 1);
    let mut fmt = WaveFormat::default();
    assert_eq!(
        format_details(FORMAT_FORMAT, &mut d, &mut fmt),
        Err(Error::NotPossible)
    );
    assert_eq!(
        format_details(9, &mut d, &mut fmt),
        Err(Error::NotSupported)
    );
}

#[test]
fn format_suggest_rejects_unusable_inputs() {
    let src = pcm(1, 8000, 8);
    let ok = Suggest {
        fdw_suggest: 0,
        cb_src: 16,
        cb_dst: 50,
    };
    let mut dst = WaveFormat::default();
    let short_src = Suggest { cb_src: 15, ..ok };
    assert_eq!(
        format_suggest(&short_src, &src, &mut dst),
        Err(Error::NotPossible)
    );
    let short_dst = Suggest { cb_dst: 15, ..ok };
    assert_eq!(
        format_suggest(&short_dst, &src, &mut dst),
        Err(Error::NotPossible)
    );
    let mut same_tag = WaveFormat {
        format_tag: WAVE_FORMAT_PCM,
        ..Default::default()
    };
    assert_eq!(
        format_suggest(&ok, &src, &mut same_tag),
        Err(Error::NotPossible)
    );
    let bad_src = WaveFormat {
        channels: 3,
        ..pcm(1, 8000, 8)
    };
    assert_eq!(
        format_suggest(&ok, &bad_src, &mut dst),
        Err(Error::NotPossible)
    );
}

#[test]
fn format_suggest_honours_preset_fields() {
    let src = pcm(1, 8000, 8);
    let all = Suggest {
        fdw_suggest: SUGGEST_WFORMATTAG
            | SUGGEST_NCHANNELS
            | SUGGEST_NSAMPLESPERSEC
            | SUGGEST_WBITSPERSAMPLE,
        cb_src: 16,
        cb_dst: 50,
    };
    let mut dst = WaveFormat {
        format_tag: WAVE_FORMAT_ADPCM,
        channels: 1,
        samples_per_sec: 8000,
        bits_per_sample: 4,
        ..Default::default()
    };
    assert_eq!(format_suggest(&all, &src, &mut dst), Ok(()));
    assert_eq!((dst.block_align, dst.samples_per_block), (256, 500));

    let pcm_out = Suggest {
        fdw_suggest: SUGGEST_NCHANNELS | SUGGEST_NSAMPLESPERSEC | SUGGEST_WBITSPERSAMPLE,
        cb_src: 16,
        cb_dst: 16,
    };
    let mut dst = WaveFormat {
        channels: 1,
        samples_per_sec: 48000,
        bits_per_sample: 8,
        ..Default::default()
    };
    assert_eq!(
        format_suggest(&pcm_out, &adpcm(1, 8000, 256), &mut dst),
        Err(Error::NotPossible)
    );
}

#[test]
fn format_suggest_refuses_unusable_adpcm_destinations() {
    let src = pcm(1, 8000, 8);
    let short = Suggest {
        fdw_suggest: 0,
        cb_src: 16,
        cb_dst: 49,
    };
    assert_eq!(
        format_suggest(&short, &src, &mut WaveFormat::default()),
        Err(Error::NotPossible)
    );

    let no_index = Suggest {
        fdw_suggest: SUGGEST_NCHANNELS | SUGGEST_NSAMPLESPERSEC | SUGGEST_WBITSPERSAMPLE,
        cb_src: 16,
        cb_dst: 50,
    };
    let mut dst = WaveFormat {
        channels: 3,
        samples_per_sec: 8000,
        bits_per_sample: 4,
        ..Default::default()
    };
    assert_eq!(
        format_suggest(&no_index, &src, &mut dst),
        Err(Error::NotPossible)
    );

    let mut dst = WaveFormat {
        format_tag: 3,
        ..Default::default()
    };
    let other_tag = Suggest {
        fdw_suggest: SUGGEST_WFORMATTAG,
        cb_src: 16,
        cb_dst: 50,
    };
    assert_eq!(
        format_suggest(&other_tag, &src, &mut dst),
        Err(Error::NotPossible)
    );

    let src = pcm(1, 48000, 16);
    let mut dst = WaveFormat {
        block_align: 6,
        cb_size: 32,
        ..Default::default()
    };
    let zero_spb = Suggest {
        fdw_suggest: 0,
        cb_src: 16,
        cb_dst: 50,
    };
    assert_eq!(
        format_suggest(&zero_spb, &src, &mut dst),
        Err(Error::NotPossible)
    );
}

#[test]
fn stream_size_covers_each_direction() {
    let pcm8 = pcm(1, 8000, 8);
    let adpcm8 = adpcm(1, 8000, 256);
    let mut s = StreamSize {
        fdw_size: SIZE_DESTINATION,
        src_length: 0,
        dst_length: 8000,
    };
    assert_eq!(stream_size(&adpcm8, &pcm8, &mut s), Ok(()));
    assert_eq!(s.src_length, 4096);

    let mut s = StreamSize {
        fdw_size: SIZE_SOURCE,
        src_length: 1001,
        dst_length: 0,
    };
    assert_eq!(stream_size(&pcm8, &adpcm8, &mut s), Ok(()));
    assert_eq!(s.dst_length, 768);

    let mut s = StreamSize {
        fdw_size: SIZE_SOURCE,
        src_length: 1000,
        dst_length: 0,
    };
    assert_eq!(stream_size(&pcm8, &adpcm8, &mut s), Ok(()));
    assert_eq!(s.dst_length, 512);

    let mut s = StreamSize {
        fdw_size: SIZE_SOURCE,
        src_length: 512,
        dst_length: 0,
    };
    assert_eq!(stream_size(&adpcm8, &pcm8, &mut s), Ok(()));
    assert_eq!(s.dst_length, 1000);

    let mut s = StreamSize {
        fdw_size: SIZE_SOURCE,
        src_length: 257,
        dst_length: 0,
    };
    assert_eq!(stream_size(&adpcm8, &pcm8, &mut s), Ok(()));
    assert_eq!(s.dst_length, 1000);
}

#[test]
fn stream_size_refuses_empty_or_unsupported_queries() {
    let pcm8 = pcm(1, 8000, 8);
    let adpcm8 = adpcm(1, 8000, 256);
    let mut s = StreamSize {
        fdw_size: SIZE_DESTINATION,
        src_length: 0,
        dst_length: 255,
    };
    assert_eq!(stream_size(&adpcm8, &pcm8, &mut s), Err(Error::NotPossible));
    s.dst_length = 0;
    assert_eq!(stream_size(&adpcm8, &pcm8, &mut s), Err(Error::NotPossible));
    assert_eq!(stream_size(&pcm8, &adpcm8, &mut s), Err(Error::NotPossible));
    s.fdw_size = SIZE_SOURCE;
    s.src_length = 0;
    assert_eq!(stream_size(&pcm8, &adpcm8, &mut s), Err(Error::NotPossible));
    assert_eq!(stream_size(&adpcm8, &pcm8, &mut s), Err(Error::NotPossible));
    let no_channels = WaveFormat {
        channels: 0,
        ..adpcm8
    };
    s.fdw_size = SIZE_DESTINATION;
    s.dst_length = 512;
    assert_eq!(
        stream_size(&pcm8, &no_channels, &mut s),
        Err(Error::NotPossible)
    );
    assert_eq!(
        stream_size(&no_channels, &pcm8, &mut s),
        Err(Error::NotPossible)
    );
    s.fdw_size = SIZE_SOURCE;
    s.src_length = 512;
    assert_eq!(
        stream_size(&pcm8, &no_channels, &mut s),
        Err(Error::NotPossible)
    );
    assert_eq!(
        stream_size(&no_channels, &pcm8, &mut s),
        Err(Error::NotPossible)
    );
    let no_align = WaveFormat {
        block_align: 0,
        ..pcm8
    };
    s.fdw_size = SIZE_DESTINATION;
    assert_eq!(
        stream_size(&adpcm8, &no_align, &mut s),
        Err(Error::NotPossible)
    );
    assert_eq!(stream_size(&pcm8, &pcm8, &mut s), Err(Error::NotSupported));
    s.fdw_size = 2;
    assert_eq!(
        stream_size(&pcm8, &adpcm8, &mut s),
        Err(Error::NotSupported)
    );
}

fn open_pair(src: WaveFormat, dst: WaveFormat) -> Result<Kind, Error> {
    stream_open(0, &src, &dst).map(|d| d.kind())
}

#[test]
fn stream_open_rejects_unsupported_streams() {
    let src = adpcm(1, 8000, 16);
    let dst = pcm(1, 8000, 16);
    assert_eq!(open_pair(src, dst), Ok(Kind::Mono));
    assert_eq!(stream_open(2, &src, &dst).err(), Some(Error::NotSupported));
    let no_index_src = WaveFormat {
        cb_size: 0,
        ..adpcm(1, 48000, 16)
    };
    assert_eq!(open_pair(no_index_src, dst), Err(Error::NotPossible));
    assert_eq!(open_pair(src, pcm(1, 48000, 8)), Err(Error::NotPossible));
    assert_eq!(open_pair(pcm(1, 8000, 16), dst), Err(Error::NotSupported));
    assert_eq!(open_pair(src, adpcm(1, 8000, 16)), Err(Error::NotSupported));
    assert_eq!(open_pair(src, pcm(1, 11025, 16)), Err(Error::NotSupported));
    assert_eq!(open_pair(src, pcm(2, 8000, 16)), Err(Error::NotSupported));
    let short_spb = WaveFormat {
        samples_per_block: 1,
        ..src
    };
    assert_eq!(open_pair(short_spb, dst), Err(Error::NotSupported));
    let odd_spb = WaveFormat {
        samples_per_block: 21,
        ..src
    };
    assert_eq!(open_pair(odd_spb, dst), Err(Error::NotSupported));
    let stereo_src = WaveFormat {
        samples_per_block: 20,
        ..adpcm(2, 8000, 16)
    };
    assert_eq!(
        open_pair(stereo_src, pcm(2, 8000, 16)),
        Err(Error::NotSupported)
    );
    let narrow_dst = WaveFormat {
        block_align: 1,
        ..dst
    };
    assert_eq!(open_pair(src, narrow_dst), Err(Error::NotSupported));
    assert_eq!(
        open_pair(adpcm(2, 8000, 64), pcm(2, 8000, 16)),
        Ok(Kind::Stereo)
    );
}

#[test]
fn stereo_eight_bit_convert_refuses_bad_headers() {
    let src = adpcm(2, 8000, 32);
    let dst = pcm(2, 8000, 8);
    let decoder = stream_open(0, &src, &dst).expect("open");
    let mut out = vec![0u8; 80];
    let usage = decoder.convert(&[0u8; 32], &mut out);
    assert_eq!(
        usage,
        Usage {
            src_used: 32,
            dst_used: 40
        }
    );
    assert!(out[..40].iter().all(|&b| b == 0x80));

    for header in [[7u8, 0], [0, 7]] {
        let mut block = [0u8; 32];
        block[..2].copy_from_slice(&header);
        let usage = decoder.convert(&block, &mut out);
        assert_eq!(
            usage,
            Usage {
                src_used: 32,
                dst_used: 4
            }
        );
    }
}

#[test]
fn derived_impls_are_exercised() {
    let f = WaveFormat::default();
    assert_eq!(f.clone(), f);
    assert!(!format!("{f:?}").is_empty());
    let c = Coef::default();
    assert_eq!(c.clone(), c);
    assert!(!format!("{c:?}").is_empty());
    let e = Error::NotPossible;
    assert_eq!(e.clone(), e);
    assert!(!format!("{e:?}").is_empty());
    let k = Kind::Mono;
    assert_eq!(k.clone(), k);
    assert!(!format!("{k:?}").is_empty());
    let dec = stream_open(0, &adpcm(1, 8000, 16), &pcm(1, 8000, 16)).expect("open");
    assert_eq!(dec.clone(), dec);
    assert!(!format!("{dec:?}").is_empty());
    let u = Usage::default();
    assert_eq!(u.clone(), u);
    assert!(!format!("{u:?}").is_empty());
    let d = driver_details();
    assert_eq!(d.clone(), d);
    assert!(!format!("{d:?}").is_empty());
    assert_eq!(
        FormatTagDetails::default().clone(),
        FormatTagDetails::default()
    );
    assert!(!format!("{:?}", FormatTagDetails::default()).is_empty());
    assert_eq!(FormatDetails::default().clone(), FormatDetails::default());
    assert!(!format!("{:?}", FormatDetails::default()).is_empty());
    assert_eq!(Suggest::default().clone(), Suggest::default());
    assert!(!format!("{:?}", Suggest::default()).is_empty());
    assert_eq!(StreamSize::default().clone(), StreamSize::default());
    assert!(!format!("{:?}", StreamSize::default()).is_empty());
}
